        defer { boltffi_free_buf(buf) }
        return try boltffiDecodeOwnedBuf(buf.ptr, Int(buf.len)) { reader in try { let tag = reader.readU8(); if tag == 0 { return () } else { throw XybridError.decode(from: &reader) } }() }
    }

